  "code": "def generated_loss(batch, model_output, extra):\\n    advantage_w = batch['advantage_w']\\n    advantage_l = batch['advantage_l']\\n    weight = batch['weight']\\n    log_prob_w = batch['log_prob_w']\\n    log_prob_l = batch['log_prob_l']\\n    loss_terms = ops.mul(ops.logsigmoid(ops.sub(advantage_w, advantage_l)), weight)\\n    loss = -ops.mean(loss_terms)\\n    return loss"
