{
  "name": "loss_margin_ranksmooth_advantage",
  "intuition": "Instead of a standard margin-based logsigmoid, this loss encourages smooth and monotonic ranking consistency by penalizing the squared difference between predicted advantage-aligned margins, promoting stability in preference gradients and sensitivity to advantage gaps.",
  "pseudocode": "advantage_score = advantage_w - advantage_l; margin = log_prob_w - log_prob_l; margin_smoothed = tanh(margin); loss = mean(weight * square(margin_smoothed - normalize(advantage_score)))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking_smooth",
    "signal_family": "advantage_gap",
    "link_family": "tanh_linear_diff",
    "agg_family": "weighted_mean",
    "constraint_family": "normalize"
  },
  "operators_used": ["tanh", "sub", "mul", "square", "mean", "normalize"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    advantage_score = ops.sub(adv_w, adv_l)\n    margin = ops.sub(lpw, lpl)\n    margin_smoothed = ops.tanh(margin)\n    norm_adv = ops.normalize(advantage_score)\n    diff = ops.sub(margin_smoothed, norm_adv)\n    loss = ops.mul(weight, ops.mul(diff, diff))\n    return ops.mean(loss)"
}

{
  "name": "pairwise_advantage_bias_loss",
  "intuition": "This loss uses the advantage signals to directly encourage better-ranked pairs by weighting the advantage difference with a logistic sigmoid. Positive advantage differences should be promoted, while negative ones are suppressed, effectively aligning the preference ordering. The sigmoid function provides smoothness and boundedness, making training stable.",
  "pseudocode": "score = logsigmoid(advantage_w - advantage_l) * weight \\n loss = - mean(score)",
