{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "Using advantage signals to weigh cost gaps emphasizes pairs where the advantage difference reflects meaningful preference, guiding the model to prioritize more relevant comparisons. This approach aligns with the observation that advantage signals encapsulate the potential improvement over baseline, hence effectively shaping preference in RL4CO.",
  "pseudocode": "loss = -ops.logsigmoid(ops.mul(extra['advantage_w'], ops.sub(batch['log_prob_w'], batch['log_prob_l']))) * ops.clip(batch['cost_gap'], 0, inf)",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "product",
    "constraint_family": "clamp"
  },
  "operators_used": ["logsigmoid", "mul", "sub", "clip"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    weight = batch['weight']\n    # Compute pairwise advantage-weighted preference\n    pref_score = ops.logsigmoid(ops.mul(advantage_w, ops.sub(log_prob_w, log_prob_l)))\n    # Clamp cost gap to ensure non-negativity\n    clamped_gap = ops.clip(cost_gap, 0, ops.inf)\n    # Final loss combines preference with cost gap emphasis\n    loss_matrix = ops.neg(ops.mul(pref_score, clamped_gap))\n    # Aggregate (e.g., mean over pairs)\n    loss = ops.mean(loss_matrix)\n    return loss"
}

{
  "name": "pairwise_contrastive_advantage_loss",
  "intuition": "This loss uses the relative advantage gap normalized by the sum of absolute advantages to focus on harder preference distinctions. Applying a sigmoid scaling emphasizes cases with significant relative advantage differences, encouraging the model to better distinguish preferred over less preferred options even when costs are close, thus improving preference modeling in RL4CO.",
  "pseudocode": "rel_adv = advantage_gap / (abs(advantage_w) + abs(advantage_l) + epsilon)\nweighting = sigmoid(scale * rel_adv)\nmargin = rel_adv * (log_prob_w - log_prob_l)\nloss = -weight * weighting * logsigmoid(margin)\nfinal_loss = mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_contrastive",
    "signal_family": "advantage_gap_relative",
    "link_family": "logsigmoid_scaled_sigmoid",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": "scale"
  },
  "operators_used": ["logsigmoid", "sigmoid", "abs", "add", "div", "mul", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    adv_gap = batch['advantage_gap']\n    scale = float(extra.get('hyperparams', {}).get('scale', 5.0))\n    eps = 1e-8\n    denom = ops.add(ops.abs(adv_w), ops.abs(adv_l))\n    denom = ops.add(denom, eps)\n    rel_adv = ops.div(adv_gap, denom)\n    weighting = ops.sigmoid(ops.mul(scale, rel_adv))\n    margin = ops.mul(rel_adv, ops.sub(lpw, lpl))\n    loss = ops.neg(ops.mul(ops.mul(weight, weighting), ops.logsigmoid(margin)))\n    return ops.mean(loss)"
}

{
  "name": "compact_advantage_gap_logsigmoid",
  "intuition": "This preference loss leverages advantage_gap to directly influence the log-probability difference, capturing the quality gap between options. Using logsigmoid on a scaled advantage_gap provides a smooth, bounded signal emphasizing the correct preference direction, especially for pairs with small gaps. The hyperparameters include scale factors to control the influence magnitude and ensure numerical stability. This approach avoids complex link functions while focusing on pairwise advantage relationships, enhancing training stability and preference alignment.",
  "pseudocode": "gap = advantage_gap.detach()\nscaled_gap = scale * gap\nx = alpha * (log_prob_w - log_prob_l) + scaled_gap\nx = clamp(x, -20, 20)\nloss = -logsigmoid(x)\nif weight is not None:\n    loss = loss * weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "scale=2.0"
  },
  "operators_used": ["logsigmoid", "clamp", "mul", "add", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "advantage_gap", "weight"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    gap = batch['advantage_gap'].detach()\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', 1.0))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    x = ops.add(ops.mul(alpha, ops.sub(lpw, lpl)), ops.mul(scale, gap))\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return loss.mean()"
}
